head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > E > onbeforerowpositionchange]<br/>DataList 모듈에서 Row 의 선택이 변경되기 전에 발생하며 반환값으로 선택을 취소할 수 있습니다.",
    "validation" : [
        "반환값으로 미설정 또는 true 설정 시 새롭게 선택될 Row 를 선택 처리한 후 onrowpositionchange 이벤트를 발생시킵니다.",
        "반환값으로 false 설정 시 Row 의 선택을 취소하고, 이전 Row 의 선택을 유지합니다. onrowpositionchange 이벤트는 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // event 바인딩
    target1.bind("onbeforerowpositionchange", function(info){
        let strReturn = par_return.getText();

        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforerowpositionchange=====");
        wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
        wf_body_bottom.getObj("scwin").setReturnValue("info.oldRowIndex : " + info.oldRowIndex);
        wf_body_bottom.getObj("scwin").setReturnValue("info.newRowIndex : " + info.newRowIndex);

        if (strReturn == "true")
            return true;
        else if (strReturn == "false")
            return false;
        else
            return;
    });      
    target1.bind("onrowpositionchange", function(e){wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onrowpositionchange=====");});    

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');
}   



scwin.btn_setColumnFilter_onclick = function (e) {
    if (isFilter) {
        target1.clearFilter();  
        isFilter = false;  
    }
    else {
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})             
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_4", condition:'or'})             
        isFilter = true;
    }	
};



scwin.btn_sort_onclick = function (e) {
    if (isSort) {    
        target1.clearSort();
        isSort = false;
    }
    else {
        target1.sort("col1", 1);
        isSort = true;
    }
};



scwin.btn_setFocusedCell_onclick = function (e) {
    gridView1.setFocusedCell(1, 0, false);  	
};
